"""Customer-scoped consultation of explicitly selected received sales lines."""
HTML='''<section class="card" id="customer-received-sales" hidden><h2>LÍNEAS DE VENTA RECIBIDAS · CLIENTE SELECCIONADO</h2><p id="customer-received-company"></p><p id="customer-received-status" role="status"></p><p>Estas líneas son referencias comerciales seleccionadas. Se consultan aparte de las facturas originales y no se suman como facturas emitidas, cobros ni salidas de almacén.</p><label>Buscar factura, SKU, descripción o archivo<input id="customer-received-query" type="search"></label><p id="customer-received-count" role="status"></p><div id="customer-received-lines" class="scroll"></div><p id="customer-received-empty" hidden></p><div class="files-actions"><button id="customer-received-files" type="button">Revisar archivos recibidos</button><button id="customer-received-prev" type="button">Anterior</button><button id="customer-received-next" type="button">Siguiente</button></div></section>'''
JS=r'''
let customerReceivedId=null,customerReceivedPage=0;
function selectedCustomerSalesLines(){return state?.info?.dataset_id===$('dataset').value&&state.selected_sales_history?.status==='SELECTED'?(state.received_sales_lines||[]):[]}
function customerReceivedSales(customerId){return selectedCustomerSalesLines().filter(line=>line.customer_id===customerId)}
function customerReceivedCounts(){const counts=new Map();selectedCustomerSalesLines().forEach(line=>counts.set(line.customer_id,(counts.get(line.customer_id)||0)+1));return counts}
function resetCustomerReceivedHistory(){customerReceivedId=null;customerReceivedPage=0;$('customer-received-sales').hidden=true;$('customer-received-query').value='';$('customer-received-lines').replaceChildren();$('customer-received-company').textContent='';$('customer-received-status').textContent='';$('customer-received-count').textContent='';$('customer-received-empty').hidden=true;$('customer-received-prev').disabled=true;$('customer-received-next').disabled=true}
function renderCustomerReceivedHistory(customerId){
 resetCustomerReceivedHistory();if(state?.info?.dataset_id!==$('dataset').value)return;const customer=(state.customers||[]).find(c=>c.customer_id===customerId);if(!customer)return;customerReceivedId=customerId;
 $('customer-received-company').textContent=state.info.company.legal_name+' · '+customer.legal_name+' / '+customer.customer_id+' · corte '+stockDate(state.info.as_of_date);$('customer-received-status').textContent=state.selected_sales_history?.message||'No hay un historial recibido seleccionado. Recibe y selecciona sus archivos desde Carga de archivos para utilizar estas referencias.';$('customer-received-sales').hidden=false;filterCustomerReceivedHistory();
}
function filterCustomerReceivedHistory(){
 if(!customerReceivedId||state?.info?.dataset_id!==$('dataset').value){resetCustomerReceivedHistory();return}const query=$('customer-received-query').value.trim().toLocaleLowerCase('es'),all=customerReceivedSales(customerReceivedId),rows=all.filter(line=>!query||[line.invoice_number,line.article_id,line.description,...line.source_refs.map(ref=>ref.filename)].join(' ').toLocaleLowerCase('es').includes(query)).sort((a,b)=>b.issue_date.localeCompare(a.issue_date)||a.invoice_number.localeCompare(b.invoice_number)||a.article_id.localeCompare(b.article_id));
 customerReceivedPage=Math.max(0,Math.min(customerReceivedPage,Math.ceil(rows.length/100)-1));const page=rows.slice(customerReceivedPage*100,(customerReceivedPage+1)*100);salesReceivedTable('customer-received-lines',page);$('customer-received-count').textContent=stockNumber(all.length)+' líneas recibidas seleccionadas para este cliente · '+stockNumber(rows.length)+' coincidencias · mostrando '+stockNumber(page.length)+' · página '+stockNumber(customerReceivedPage+1)+' de '+stockNumber(Math.max(1,Math.ceil(rows.length/100)))+'. No son un recuento de facturas completas.';$('customer-received-empty').hidden=page.length>0;$('customer-received-empty').textContent=all.length?'No hay líneas que coincidan con esta búsqueda.':'Sin líneas recibidas seleccionadas para este cliente. Consulta el estado del historial y las facturas originales mostradas arriba.';$('customer-received-prev').disabled=customerReceivedPage===0;$('customer-received-next').disabled=(customerReceivedPage+1)*100>=rows.length;
}
$('customer-received-files').onclick=()=>view('archivos');
$('customer-received-query').addEventListener('input',()=>{customerReceivedPage=0;filterCustomerReceivedHistory()});$('customer-received-prev').onclick=()=>{customerReceivedPage--;filterCustomerReceivedHistory()};$('customer-received-next').onclick=()=>{customerReceivedPage++;filterCustomerReceivedHistory()};
'''
